-- The identity migration installed older per-table triggers; the unified guard replaces them.
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['users','profiles','blocks','blocklist_entries','notification_preferences',
                           'devices','user_restrictions','policy_versions','consent_records'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', t || '_prevent_delete', t);
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', t || '_never_delete', t);
    EXECUTE format('DROP FUNCTION IF EXISTS %I()', t || '_prevent_delete_func');
    EXECUTE format('DROP FUNCTION IF EXISTS %I()', t || '_never_delete_func');
  END LOOP;
END
$$;

-- Admin auth events are immutable (append-only).
DROP TRIGGER IF EXISTS block_update ON admin_auth_events;
CREATE TRIGGER block_update BEFORE UPDATE ON admin_auth_events
  FOR EACH ROW EXECUTE FUNCTION block_update();

DROP FUNCTION IF EXISTS create_soft_delete_trigger(text);
DROP FUNCTION IF EXISTS create_never_delete_trigger(text);
